/** WinUI on Web 插件安装选项 */
export interface WinUIInstallOptions {
  /** 国际化语言，默认自动检测浏览器语言 */
  locale?: string
  /** 额外的国际化资源 */
  extraResources?: Partial<ResourceBundle>
  /** 是否注册所有组件为全局组件，默认 true */
  registerAll?: boolean
  /** 是否挂载 $t 全局方法，默认 true */
  installGlobalProperties?: boolean
}

/**
 * Vue 插件
 *
 * @example
 * import { createApp } from 'vue'
 * import WinUI from 'winuionweb'
 * const app = createApp(App)
 * app.use(WinUI, { locale: 'zh-CN' })
 * app.mount('#app')
 */
const plugin = {
  install(app: App, options?: WinUIInstallOptions) {
    const { registerAll = true, installGlobalProperties = true } = options ?? {}

    // 1. 初始化国际化
    const i18n = createI18n(
      options?.locale ?? (typeof navigator !== 'undefined' ? navigator.language : 'en-US'),
      options?.extraResources,
    )
    app.provide(i18nKey, i18n)
    if (installGlobalProperties) {
      app.config.globalProperties.$t = i18n.t
    }

    // 2. 全局注册组件
    if (registerAll) {
      const components: Record<string, any> = {
        Grid: CompGrid,
        StackPanel: CompStackPanel,
        RelativePanel: CompRelativePanel,
        VariableSizedWrapGrid: CompVariableSizedWrapGrid,
        Border: CompBorder,
        Canvas: CompCanvas,
        Rectangle: CompRectangle,
        Viewbox: CompViewbox,
        GridColumnDefinitions: CompGridColumnDefinitions,
        GridRowDefinitions: CompGridRowDefinitions,
        ColumnDefinition: CompColumnDefinition,
        RowDefinition: CompRowDefinition,
        GridDefinitions: CompGridDefinitions,
        TextBlock: CompTextBlock,
        TextBox: CompTextBox,
        RichEditBox: CompRichEditBox,
        RichTextBlock: CompRichTextBlock,
        PasswordBox: CompPasswordBox,
        AutoSuggestBox: CompAutoSuggestBox,
        NumberBox: CompNumberBox,
        Button: CompButton,
        ToggleButton: CompToggleButton,
        RepeatButton: CompRepeatButton,
        HyperlinkButton: CompHyperlinkButton,
        DropDownButton: CompDropDownButton,
        SplitButton: CompSplitButton,
        ToggleSplitButton: CompToggleSplitButton,
        AppBarButton: CompAppBarButton,
        AppBarToggleButton: CompAppBarToggleButton,
        AppBarSeparator: CompAppBarSeparator,
        CheckBox: CompCheckBox,
        RadioButton: CompRadioButton,
        RadioButtons: CompRadioButtons,
        ToggleSwitch: CompToggleSwitch,
        Slider: CompSlider,
        Rating: CompRating,
        ColorPicker: CompColorPicker,
        ComboBox: CompComboBox,
        ListBox: CompListBox,
        DatePicker: CompDatePicker,
        TimePicker: CompTimePicker,
        CalendarDatePicker: CompCalendarDatePicker,
        CalendarView: CompCalendarView,
        ListView: CompListView,
        GridView: CompGridView,
        FlipView: CompFlipView,
        ItemsView: CompItemsView,
        ItemsRepeater: CompItemsRepeater,
        TreeView: CompTreeView,
        PickerColumn: CompPickerColumn,
        Flyout: CompFlyout,
        FlyoutAnimation: CompFlyoutAnimation,
        MenuFlyout: CompMenuFlyout,
        ContentDialog: CompContentDialog,
        Popup: CompPopup,
        TeachingTip: CompTeachingTip,
        ToolTip: CompToolTip,
        ToolTipService: CompToolTipService,
        CommandBarFlyout: CompCommandBarFlyout,
        MenuBar: CompMenuBar,
        CommandBar: CompCommandBar,
        SplitView: CompSplitView,
        NavigationView: CompNavigationView,
        Pivot: CompPivot,
        PivotItem: CompPivotItem,
        SelectorBar: CompSelectorBar,
        SelectorBarItem: CompSelectorBarItem,
        BreadcrumbBar: CompBreadcrumbBar,
        PipsPager: CompPipsPager,
        ProgressBar: CompProgressBar,
        ProgressRing: CompProgressRing,
        InfoBar: CompInfoBar,
        InfoBadge: CompInfoBadge,
        ScrollViewer: CompScrollViewer,
        ScrollView: CompScrollView,
        ScrollBar: CompScrollBar,
        AnnotatedScrollBar: CompAnnotatedScrollBar,
        HorizontalScrollContainer: CompHorizontalScrollContainer,
        PullToRefresh: CompPullToRefresh,
        RefreshContainer: CompRefreshContainer,
        RefreshVisualizer: CompRefreshVisualizer,
        Image: CompImage,
        MediaPlayerElement: CompMediaPlayerElement,
        CaptureElement: CompCaptureElement,
        PersonPicture: CompPersonPicture,
        AnimatedVisualPlayer: CompAnimatedVisualPlayer,
        ParallaxView: CompParallaxView,
        FontIcon: CompFontIcon,
        SymbolIcon: CompSymbolIcon,
        Expander: CompExpander,
        ExpanderBase: CompExpanderBase,
        SwipeControl: CompSwipeControl,
        Case: CompCase,
        SwitchPresenter: CompSwitchPresenter,
        SettingsCard: CompSettingsCard,
        SemanticZoom: CompSemanticZoom,
        TitleBar: CompTitleBar,
        TypographyRow: CompTypographyRow,
        PageHeader: CompPageHeader,
        ControlExample: CompControlExample,
        ControlExampleBase: CompControlExampleBase,
        ThemeWrapper: CompThemeWrapper,
        // XAML 子属性组件（用点号名称注册，支持 XAML 语法）
        'Button.Flyout': CompButtonFlyout,
        'SplitButton.Flyout': CompSplitButtonFlyout,
        'ToggleSplitButton.Flyout': CompToggleSplitButtonFlyout,
        'ControlExample.Example': CompControlExampleExample,
        'ControlExample.Output': CompControlExampleOutput,
        'ControlExample.Options': CompControlExampleOptions,
        'Expander.Header': CompExpanderHeader,
        'Expander.Content': CompExpanderContent,
        'Expander.Description': CompExpanderDescription,
        'Expander.HeaderIcon': CompExpanderHeaderIcon,
        'Expander.HeaderControls': CompExpanderHeaderControls,
        'TeachingTip.HeroContent': CompTeachingTipHeroContent,
        'TeachingTip.Content': CompTeachingTipContent,
        'TeachingTip.IconSource': CompTeachingTipIconSource,
        'DropDownButton.Flyout': CompDropDownButtonFlyout,
        'DropDownButton.Content': CompDropDownButtonContent,
        'ToolTipService.ToolTip': CompToolTipServiceToolTip,
        MenuFlyoutItem: CompMenuFlyoutItem,
        'MenuFlyoutItem.Icon': CompMenuFlyoutItemIcon,
      }

      for (const [name, comp] of Object.entries(components)) {
        if (comp) {
          app.component(name, comp)
        }
      }
    }
  },
}

export default plugin